# DATABASE
# ══════════════════════════════════════════════════════════════
def init_db():
    con = sqlite3.connect(DB_FILE)
    con.executescript("""
        CREATE TABLE IF NOT EXISTS pages (
            id      INTEGER PRIMARY KEY AUTOINCREMENT,
            url     TEXT UNIQUE,
            title   TEXT,
            content TEXT,
            crawled TEXT
        );
        CREATE VIRTUAL TABLE IF NOT EXISTS pages_fts
            USING fts5(url,title,content,
                       content=pages, content_rowid=id);
        CREATE TABLE IF NOT EXISTS visited (
            url TEXT PRIMARY KEY
        );
    """)
    con.commit(); con.close()

def db_save(url, title, content):
    try:
        con = sqlite3.connect(DB_FILE)
        cur = con.cursor()
        cur.execute("""INSERT OR REPLACE INTO pages
            (url,title,content,crawled) VALUES(?,?,?,?)""",
            (url, title, content[:80000],
             datetime.now().isoformat()))
        rid = cur.lastrowid
        cur.execute("""INSERT OR REPLACE INTO pages_fts
            (rowid,url,title,content) VALUES(?,?,?,?)""",
            (rid, url, title, content[:80000]))
        cur.execute("INSERT OR IGNORE INTO visited VALUES(?)",(url,))
        con.commit(); con.close()
    except: pass

def db_search(query, limit=40):
    try:
        con = sqlite3.connect(DB_FILE)
        cur = con.cursor()
        # FTS zoekopdracht
        try:
            cur.execute("""
                SELECT p.url, p.title,
                       snippet(pages_fts,2,'[',']','...',25)
                FROM pages_fts
                JOIN pages p ON pages_fts.rowid=p.id
                WHERE pages_fts MATCH ?
                ORDER BY rank LIMIT ?""", (query, limit))
            rows = cur.fetchall()
        except: rows = []
        # LIKE fallback
        if not rows:
            lk = f"%{query}%"
            cur.execute("""SELECT url,title,substr(content,1,200)
                FROM pages WHERE title LIKE ? OR content LIKE ?
                LIMIT ?""", (lk,lk,limit))
            rows = cur.fetchall()
        con.close()
        return rows
    except: return []

def db_stats():
    try:
        con = sqlite3.connect(DB_FILE)
        cur = con.cursor()
        cur.execute("SELECT COUNT(*) FROM pages")
        p = cur.fetchone()[0]
        cur.execute("SELECT COUNT(*) FROM visited")
        v = cur.fetchone()[0]
        con.close()
        return p, v
    except: return 0, 0

