# AD BLOCKER
# ══════════════════════════════════════════════════════════════
AD_DOMAINS = {
    "doubleclick.net","googlesyndication.com","googleadservices.com",
    "adnxs.com","advertising.com","criteo.com","pubmatic.com",
    "rubiconproject.com","openx.net","appnexus.com",
    "scorecardresearch.com","quantserve.com","hotjar.com",
    "mixpanel.com","google-analytics.com","googletagmanager.com",
    "facebook.com/tr","connect.facebook.net","amazon-adsystem.com",
}

class AdBlocker(QWebEngineUrlRequestInterceptor):
    def interceptRequest(self, info):
        host = info.requestUrl().host().lower()
        url  = info.requestUrl().toString()
        for d in AD_DOMAINS:
            if d in host or d in url:
                info.block(True); return

# ══════════════════════════════════════════════════════════════
# HTML PARSER
# ══════════════════════════════════════════════════════════════
class LinkParser(HTMLParser):
    def __init__(self, base=""):
        super().__init__()
        self.links=[]; self.title=""; self._parts=[]
        self.base=base; self._t=False
        self._skip={"script","style","noscript","svg","header",
                    "footer","nav","aside"}
        self._in_skip=False

    def handle_starttag(self, tag, attrs):
        if tag=="title": self._t=True
        if tag in self._skip: self._in_skip=True
        if tag=="a":
            for k,v in attrs:
                if k=="href" and v:
                    try:
                        full=urllib.parse.urljoin(self.base,v)
                        if full.startswith("http"):
                            self.links.append(full)
                    except: pass

    def handle_endtag(self, tag):
        if tag=="title": self._t=False
        if tag in self._skip: self._in_skip=False

    def handle_data(self, data):
        if self._t: self.title+=data
        elif not self._in_skip:
            t=data.strip()
            if t: self._parts.append(t)

    def get_text(self): return " ".join(self._parts)

# ══════════════════════════════════════════════════════════════
# FETCH HELPER
# ══════════════════════════════════════════════════════════════
def fetch_page(url, use_tor=False, timeout=8):
    try:
        req = urllib.request.Request(url, headers={
            "User-Agent":
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 (KHTML, like Gecko) "
                "Chrome/120.0 Safari/537.36",
            "Accept": "text/html,application/xhtml+xml;q=0.9,*/*;q=0.8",
            "Accept-Language": "nl,en-US;q=0.8,en;q=0.5",
            "Accept-Encoding": "identity",  # Geen gzip = geen encoding problemen
        })
        if use_tor:
            try:
                import socks, socket
                socks.set_default_proxy(
                    socks.SOCKS5,"127.0.0.1",TOR_PORT)
                socket.socket=socks.socksocket
            except: pass
        with urllib.request.urlopen(req, timeout=timeout) as r:
            ct = r.headers.get("Content-Type","")
            if "text/html" not in ct: return None
            raw = r.read(500_000)
            # Detecteer encoding uit Content-Type header
            enc = r.headers.get_content_charset(None)
            # Als geen encoding in header, detecteer uit HTML meta tag
            if not enc:
                sniff = raw[:2000].lower()
                m = re.search(rb'charset=["\']?([\w-]+)', sniff)
                enc = m.group(1).decode() if m else "utf-8"
            try:
                return raw.decode(enc, errors="replace")
            except:
                return raw.decode("utf-8", errors="replace")
    except: return None

# ══════════════════════════════════════════════════════════════
# ZOEK THREAD — Slim zoeken op het echte internet
# ══════════════════════════════════════════════════════════════
class SearchThread(QThread):
    found   = pyqtSignal(str, str, str)  # url, title, snippet
    status  = pyqtSignal(str)
    done    = pyqtSignal(int)

    SKIP_EXT = {".pdf",".zip",".exe",".mp4",".mp3",".jpg",
                ".jpeg",".png",".gif",".svg",".ico",".css",
                ".js",".woff",".woff2",".ttf"}
    SKIP_HOSTS = {
        "wikipedia.org","wikimedia.org","wikibooks.org",
        "wikivoyage.org","wikinews.org","wiktionary.org",
        "wikiquote.org","mediawiki.org","wikidata.org",
        "openlibrary.org","archive.org",
    }

    def __init__(self, query, use_tor=False):
        super().__init__()
        self.query   = query
        self.use_tor = use_tor
        self._stop   = False
        self._found  = 0
        self._seen   = set()

    def run(self):
        q     = self.query
        words = [w.lower() for w in q.split() if len(w)>2]
        enc   = urllib.parse.quote_plus(q)

        self.status.emit(f"🔍 Zoeken naar: {q}")

        # ── Stap 1: Privé zoekmachines — geen Wikipedia, geen tracking ──
        search_urls = [
            # DuckDuckGo Lite — privé, geen JS, geen tracking
            f"https://lite.duckduckgo.com/lite/?q={enc}",
            # Brave Search — eigen index, privé
            f"https://search.brave.com/search?q={enc}&source=web",
            # Mojeek — onafhankelijke eigen index, geen tracking
            f"https://www.mojeek.com/search?q={enc}",
            # Marginalia — klein maar uniek, geen grote sites
            f"https://search.marginalia.nu/search?query={enc}",
            # Ekoru — privé zoekmachine
            f"https://www.ekoru.org/?q={enc}",
            # Swisscows — privé, Zwitserse servers
            f"https://swisscows.com/web?query={enc}",
            # Metager — Duits, open source, privé
            f"https://metager.org/meta/meta.ger3?eingabe={enc}&lang=nl",
            # Searx publieke instantie — geen tracking
            f"https://searx.be/search?q={enc}&format=html",
            f"https://searx.tiekoetter.com/search?q={enc}&format=html",
        ]


        all_urls = set()

        for search_url in search_urls:
            if self._stop: break
            try:
                self.status.emit(
                    f"🌐 {urllib.parse.urlparse(search_url).netloc}...")
                html = fetch_page(search_url, self.use_tor)
                if not html: continue

                parser = LinkParser(search_url)
                parser.feed(html)

                # Filter links — alleen externe links, geen zoeksite zelf
                base_host = urllib.parse.urlparse(search_url).netloc
                # Volg ook sub-paginas van de zoeksite voor meer resultaten
                for link in parser.links[:200]:
                    if self._stop: break

                    # Uitpakken van DuckDuckGo redirect links
                    real_link = link
                    if "duckduckgo.com/l/" in link:
                        try:
                            qs = urllib.parse.urlparse(link).query
                            params = urllib.parse.parse_qs(qs)
                            real_link = params.get("uddg", [link])[0]
                            real_link = urllib.parse.unquote(real_link)
                        except: real_link = link

                    # Uitpakken van andere redirect links
                    if "brave.com/search" in real_link or                        "mojeek.com/search" in real_link:
                        try:
                            qs = urllib.parse.urlparse(real_link).query
                            params = urllib.parse.parse_qs(qs)
                            for key in ["url","u","href","link"]:
                                if key in params:
                                    real_link = urllib.parse.unquote(
                                        params[key][0])
                                    break
                        except: pass

                    if not real_link.startswith("http"):
                        continue

                    lhost = urllib.parse.urlparse(real_link).netloc.lower()
                    # Skip de zoeksite zelf
                    if lhost == base_host: continue
                    # Skip bekende zoeksite domeinen
                    search_hosts = {"duckduckgo.com","brave.com",
                        "mojeek.com","searx.be","metager.org",
                        "ekoru.org","swisscows.com","marginalia.nu",
                        "searx.tiekoetter.com"}
                    if any(sh in lhost for sh in search_hosts): continue
                    # Skip wiki en archive
                    skip_this = False
                    for skip in self.SKIP_HOSTS:
                        if skip in lhost:
                            skip_this = True; break
                    if skip_this: continue
                    # Skip ongewenste extensies
                    ext = os.path.splitext(
                        urllib.parse.urlparse(real_link).path)[1].lower()
                    if ext in self.SKIP_EXT: continue
                    if real_link not in self._seen:
                        all_urls.add(real_link)
                        self._seen.add(real_link)
            except: continue

        self.status.emit(
            f"📋 {len(all_urls)} URLs gevonden, inhoud laden...")

        # ── Stap 2: crawl elke gevonden URL ──────────────────────
        for url in list(all_urls):
            if self._stop: break
            self._process_url(url, words)


        # ── Stap 3: dieper via gevonden links ──────────────────
        if not self._stop:
            self.status.emit("🔎 Dieper zoeken via gevonden links...")
            extra = [u for u in self._seen if u not in all_urls]
            for url in extra[:150]:
                if self._stop: break
                try:
                    html = fetch_page(url, self.use_tor)
                    if not html: continue
                    p2 = LinkParser(url)
                    p2.feed(html)
                    for link in list(set(p2.links))[:20]:
                        if self._stop: break
                        if link not in self._seen:
                            self._seen.add(link)
                            self._process_url(link, words)
                except: continue

        # ── Stap 4: nog dieper als < 20 resultaten ───────────────
        if self._found < 20 and not self._stop:
            self.status.emit("🕸 Nog dieper zoeken...")
            deep = [u for u in self._seen if u not in all_urls]
            for url in deep[150:350]:
                if self._stop: break
                self._process_url(url, words)

        # ── Stap 3: als nog weinig resultaten, volg sub-links ────
        if self._found < 8 and not self._stop:
            self.status.emit("🔎 Dieper zoeken...")
            extra = list(self._seen)[:30]
            for url in extra:
                if self._stop: break
                try:
                    html = fetch_page(url, self.use_tor)
                    if not html: continue
                    p = LinkParser(url)
                    p.feed(html)
                    for link in list(set(p.links))[:10]:
                        if self._stop: break
                        if link not in self._seen:
                            self._seen.add(link)
                            self._process_url(link, words)
                except: continue

        self.status.emit(
            f"✅ Klaar — {self._found} resultaten gevonden")
        self.done.emit(self._found)

    def _process_url(self, url, words):
        """Haal pagina op, check relevantie, sla op en emit."""
        try:
            host = urllib.parse.urlparse(url).netloc.lower()
            # Filter wiki en archive sites
            for skip in self.SKIP_HOSTS:
                if skip in host: return
            ext = os.path.splitext(
                urllib.parse.urlparse(url).path)[1].lower()
            if ext in self.SKIP_EXT: return

            self.status.emit(
                f"📄 {urllib.parse.urlparse(url).netloc}...")
            html = fetch_page(url, self.use_tor)
            if not html: return

            p = LinkParser(url)
            p.feed(html)
            title   = p.title.strip() or url
            content = p.get_text()

            # Relevantie score
            haystack = (title+" "+content).lower()
            score = sum(1 for w in words if w in haystack)
            if score == 0: return

            # Maak snippet
            snippet = self._snippet(content, words)

            # Sla op in index
            db_save(url, title, content)
            self.found.emit(url, title, snippet)
            self._found += 1

            # Voeg sub-links toe aan seen voor later
            for link in p.links[:20]:
                self._seen.add(link)

        except: pass

    def _snippet(self, text, words, length=180):
        tl = text.lower()
        for w in words:
            i = tl.find(w)
            if i >= 0:
                s = max(0, i-60)
                e = min(len(text), i+length)
                pfx = "..." if s>0 else ""
                return pfx + text[s:e].strip() + "..."
        return text[:length].strip() + "..."

    def stop(self): self._stop = True

# ══════════════════════════════════════════════════════════════
# ACHTERGROND CRAWLER
# ══════════════════════════════════════════════════════════════
class BgCrawler(QThread):
    status = pyqtSignal(str, int, int)
    done   = pyqtSignal()

    SKIP_EXT = {".pdf",".zip",".exe",".mp4",".mp3",".jpg",
                ".jpeg",".png",".gif",".svg",".ico",".css",
                ".js",".woff"}

    def __init__(self, seed_urls, use_tor=False, delay=1.5):
        super().__init__()
        self.seeds   = seed_urls
        self.use_tor = use_tor
        self.delay   = delay
        self._stop   = False

    def run(self):
        queue   = list(self.seeds)
        visited = set()
        pages   = 0

        while queue and not self._stop:
            url = queue.pop(0)
            if url in visited: continue
            visited.add(url)

            ext = os.path.splitext(
                urllib.parse.urlparse(url).path)[1].lower()
            if ext in self.SKIP_EXT: continue

            try:
                html = fetch_page(url, self.use_tor)
                if not html: continue

                p = LinkParser(url)
                p.feed(html)
                title   = p.title.strip() or url
                content = p.get_text()

                db_save(url, title, content)
                pages += 1

                # Voeg links toe
                for link in p.links:
                    if link not in visited:
                        queue.append(link)

                pg, vs = db_stats()
                self.status.emit(
                    f"🕷 {title[:45]}", pg, vs)
                time.sleep(self.delay)

            except: continue

        self.done.emit()

    def stop(self): self._stop = True

# ══════════════════════════════════════════════════════════════
# TOR MANAGER
# ══════════════════════════════════════════════════════════════
class TorManager(QThread):
    status = pyqtSignal(str)
    ready  = pyqtSignal(bool)

    def __init__(self): super().__init__(); self._proc=None

    def run(self):
        self.status.emit("🧅 Tor controleren...")
        if not os.path.exists(TOR_EXE):
            self.status.emit("⬇ Tor downloaden (even geduld)...")
            if not self._download():
                self.status.emit("❌ Tor download mislukt")
                self.ready.emit(False); return
        self.status.emit("🧅 Tor opstarten...")
        try:
            os.makedirs(os.path.join(TOR_DIR,"data"), exist_ok=True)
            self._proc = __import__("subprocess").Popen(
                [TOR_EXE,"--SocksPort",str(TOR_PORT),
                 "--DataDirectory",os.path.join(TOR_DIR,"data")],
                stdout=__import__("subprocess").PIPE,
                stderr=__import__("subprocess").PIPE,
                creationflags=(
                    __import__("subprocess").CREATE_NO_WINDOW
                    if sys.platform=="win32" else 0))
            for _ in range(60):
                time.sleep(1)
                if self._check():
                    self.status.emit("✅ Tor verbonden!")
                    self.ready.emit(True); return
            self.status.emit("❌ Tor time-out")
            self.ready.emit(False)
        except Exception as e:
            self.status.emit(f"❌ {e}")
            self.ready.emit(False)

    def _check(self):
        import socket
        try:
            s=socket.socket(); s.settimeout(1)
            s.connect(("127.0.0.1",TOR_PORT)); s.close()
            return True
        except: return False

    def _download(self):
        try:
            import tarfile
            os.makedirs(TOR_DIR, exist_ok=True)
            url=("https://archive.torproject.org/tor-package-archive/"
                 "torbrowser/13.0.16/"
                 "tor-expert-bundle-windows-x86_64-13.0.16.tar.gz")
            dest=os.path.join(TOR_DIR,"tor.tar.gz")
            urllib.request.urlretrieve(url, dest)
            with tarfile.open(dest) as t: t.extractall(TOR_DIR)
            for root,dirs,files in os.walk(TOR_DIR):
                for f in files:
                    if f.lower()=="tor.exe":
                        src=os.path.join(root,f)
                        if src!=TOR_EXE:
                            import shutil
                            shutil.copy2(src,TOR_EXE)
                        return True
        except: pass
        return False

    def stop(self):
        if self._proc:
            try:
                self._proc.terminate()
                self._proc.wait(timeout=3)
            except: pass
            # Forceer afsluiten via taskkill op Windows
            try:
                import subprocess
                subprocess.run(
                    ["taskkill", "/F", "/IM", "tor.exe"],
                    creationflags=subprocess.CREATE_NO_WINDOW,
                    timeout=3)
            except: pass
            self._proc = None

