# RESULTAAT KAART
# ══════════════════════════════════════════════════════════════
class ResultCard(QFrame):
    clicked = pyqtSignal(str)

    def __init__(self, url, title, snippet):
        super().__init__()
        self.url = url
        self.setCursor(QCursor(Qt.CursorShape.PointingHandCursor))
        self.setStyleSheet("""
            ResultCard {
                background:#111118;
                border:1px solid rgba(200,205,214,0.08);
                border-radius:10px;
            }
            ResultCard:hover {
                background:#16161f;
                border-color:rgba(126,184,247,0.3);
            }
        """)
        ly = QVBoxLayout(self)
        ly.setContentsMargins(12,10,12,10)
        ly.setSpacing(3)

        # Titel
        t = QLabel(title[:90] if title else url[:90])
        t.setStyleSheet("color:#e8ecf2;font-size:14px;font-weight:800;")
        t.setWordWrap(True)
        ly.addWidget(t)

        # URL
        host = urllib.parse.urlparse(url).netloc
        u = QLabel(host)
        u.setStyleSheet("color:#7eb8f7;font-size:12px;font-weight:600;")
        ly.addWidget(u)

        # Snippet
        if snippet:
            s = QLabel(snippet[:200])
            s.setStyleSheet("color:#b0b0c0;font-size:12px;")
            s.setWordWrap(True)
            ly.addWidget(s)

    def mousePressEvent(self, e):
        if e.button()==Qt.MouseButton.LeftButton:
            self.clicked.emit(self.url)

