class DravenCrawlWindow(QMainWindow):

    def __init__(self):
        super().__init__()
        self.setWindowTitle(f"DravenCrawl v{VERSION}")
        self.setWindowIcon(logo_icon())
        self.resize(1400, 860)
        self._tor_on      = False
        self._tor_mgr     = None
        self._search_thr  = None
        self._bg_crawler  = None
        init_db()
        self._build_ui()
        self._setup_browser()
        QTimer.singleShot(500, self._refresh_stats)
        # Tor standaard aanzetten bij opstarten
        QTimer.singleShot(1000, self._start_tor_default)

    # ── Browser instellen ──────────────────────────────────────
    def _setup_browser(self):
        profile = QWebEngineProfile.defaultProfile()
        self._blocker = AdBlocker()
        profile.setUrlRequestInterceptor(self._blocker)
        profile.setHttpUserAgent(
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
            "AppleWebKit/537.36 Chrome/120.0 DravenCrawl/"+VERSION)
        s = profile.settings()
        s.setAttribute(
            QWebEngineSettings.WebAttribute.JavascriptCanOpenWindows,
            False)
        # Cookie banner auto-sluiter via JavaScript injectie
        self.webview.loadFinished.connect(self._inject_cookie_killer)
        self._show_home()

    COOKIE_KILLER_JS = r"""
(function() {
    const REJECT = [
        'weigeren','refuse','decline','reject all','alles weigeren',
        'alleen noodzakelijk','necessary only','only necessary',
        'noodzakelijk','minimaal','minimal'
    ];
    const ACCEPT = [
        'accepteer alle','accepteer alles','accept all','alle cookies',
        'alle accepteren','alles accepteren','akkoord','agree',
        'toestaan','allow all','ok','oke','sluiten','close',
        'got it','begrepen','selectie accepteren','accept','verstaan',
        'ja, ik ga akkoord','confirm','bevestigen'
    ];

    function findAndClick(words) {
        // Zoek alle klikbare elementen
        var els = Array.from(document.querySelectorAll(
            'button, a, input[type=button], input[type=submit], ' +
            '[role=button], [onclick], ' +
            '[class*=cookie] button, [class*=consent] button, ' +
            '[class*=gdpr] button, [id*=cookie] button, ' +
            '[class*=banner] button, [class*=privacy] button, ' +
            '[class*=notice] button, [class*=popup] button'));
        for (var w of words) {
            for (var el of els) {
                var txt = (el.innerText || el.textContent ||
                           el.value || '').toLowerCase().trim();
                if (txt === w || txt.startsWith(w) ||
                    (txt.length < 40 && txt.includes(w))) {
                    if (el.offsetParent !== null ||
                        el.offsetWidth > 0) {
                        try {
                            el.click();
                            return true;
                        } catch(e) {}
                    }
                }
            }
        }
        return false;
    }

    function removeOverlays() {
        // Verwijder overlay/backdrop elementen
        var sels = [
            '[class*=cookie-overlay]','[class*=consent-overlay]',
            '[class*=cookie-backdrop]','[class*=cookie-wall]',
            '[id*=cookie-overlay]','[id*=cookiebanner]',
            '[class*=cookiebanner]','[id*=cookieConsent]',
            '[class*=cookie-notice]','[class*=cookie-popup]',
            '[class*=cookie-bar]','[id*=cookie-bar]',
            '[class*=cc-banner]','[id*=cc-banner]',
            '.fc-consent-root','.qc-cmp2-container',
            '#onetrust-banner-sdk','.osano-cm-window',
            '#cookielaw-info-bar','#cookie-law-info-bar',
            '.cookie-law-info-bar','.pea_cook_wrapper',
        ];
        for (var s of sels) {
            try {
                document.querySelectorAll(s).forEach(
                    function(el) { el.remove(); });
            } catch(e) {}
        }
        // Herstel scroll als die geblokkeerd was
        try {
            document.body.style.overflow = '';
            document.documentElement.style.overflow = '';
        } catch(e) {}
    }

    function run() {
        // Probeer eerst weigeren, dan accepteren
        var clicked = findAndClick(REJECT);
        if (!clicked) clicked = findAndClick(ACCEPT);
        if (clicked) {
            setTimeout(removeOverlays, 400);
        } else {
            removeOverlays();
        }
    }

    // Meerdere pogingen op verschillende tijdstippen
    setTimeout(run, 600);
    setTimeout(run, 1500);
    setTimeout(run, 3000);
})();
"""

