    # ── Zoeken ────────────────────────────────────────────────
    def _search(self):
        q = self.qbar.text().strip()
        if not q: return

        # URL? Dan direct navigeren
        if not " " in q and ("." in q or q.startswith("http")):
            url = q if q.startswith("http") else "https://"+q
            self.url_bar.setText(url)
            self.webview.setUrl(QUrl(url)); return

        # Stop vorige zoekopdracht
        if self._search_thr and self._search_thr.isRunning():
            self._search_thr.stop()
            self._search_thr.wait(1000)

        # Verwijder vorige resultaten
        self._clear_results()
        self.panel_title.setText("Zoeken...")
        self.res_count.setText("")

        # Toon laad indicator
        lbl = QLabel(f"🔍 Zoeken naar: {q}\n\nEven geduld...")
        lbl.setObjectName("loading_lbl")
        lbl.setStyleSheet(
            "color:#7eb8f7;font-size:12px;padding:20px;"
            "background:#111118;border-radius:10px;")
        lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        lbl.setWordWrap(True)
        self.res_ly.insertWidget(0, lbl)

        # Toon stop knop
        self.stop_search_btn.setVisible(True)

        # Start zoekthread
        self._search_thr = SearchThread(q, self._tor_on)
        self._search_thr.found.connect(self._on_result)
        self._search_thr.status.connect(
            lambda s: self.crawl_status.setText(s))
        self._search_thr.done.connect(self._on_search_done)
        self._search_thr.start()

    def _do_db_search(self):
        """Zoek in de lokale DravenCrawl database."""
        q = self.db_bar.text().strip()
        if not q: return

        # Verwijder oude resultaten
        self._clear_results()
        self.panel_title.setText("Index zoeken...")
        self.res_count.setText("")

        results = []
        try:
            con = sqlite3.connect(DB_FILE)
            cur = con.cursor()
            # FTS zoekopdracht
            try:
                cur.execute("""
                    SELECT p.url, p.title,
                        snippet(pages_fts,2,'[',']','...',25)
                    FROM pages_fts
                    JOIN pages p ON pages_fts.rowid=p.id
                    WHERE pages_fts MATCH ?
                    ORDER BY rank LIMIT 60""", (q,))
                results = cur.fetchall()
            except: pass
            # LIKE fallback
            if not results:
                lk = f"%{q}%"
                cur.execute("""SELECT url, title,
                    substr(content,1,200)
                    FROM pages
                    WHERE title LIKE ? OR content LIKE ? OR url LIKE ?
                    LIMIT 60""", (lk, lk, lk))
                results = cur.fetchall()
            con.close()
        except Exception as e:
            self.crawl_status.setText(f"⚠ DB fout: {e}")
            return

        self.panel_title.setText("Resultaten")
        self.res_count.setText(f"{len(results)} in index")
        self.crawl_status.setText(
            f"🗄 {len(results)} resultaten uit index voor: {q}")
        self.crawl_status.setStyleSheet(
            "color:#7ec87e;font-size:12px;font-weight:600;")

        if not results:
            lbl = QLabel(
                f"Niets gevonden voor '{q}' in de index.\n"
                "Gebruik de zoekbalk bovenaan om het web te doorzoeken.")
            lbl.setStyleSheet(
                "color:#a0a0b8;font-size:12px;padding:16px;"
                "background:#111118;border-radius:10px;margin:4px;")
            lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
            lbl.setWordWrap(True)
            self.res_ly.insertWidget(0, lbl)
            return

        for url, title, snippet in results:
            # Schoon snippet op
            snip = (snippet or "").replace("{","").replace("}","")
            snip = " ".join(snip.split())
            if snip.startswith(("e()", "gtag", "window", "@")):
                snip = ""
            card = ResultCard(url, title, snip)
            card.clicked.connect(self._open)
            count = self.res_ly.count()
            self.res_ly.insertWidget(count-1, card)

    def _stop_search(self):
        if self._search_thr and self._search_thr.isRunning():
            self._search_thr.stop()
        self.stop_search_btn.setVisible(False)
        self.panel_title.setText("Resultaten")

    def _on_search_done(self, n):
        self.stop_search_btn.setVisible(False)
        self.panel_title.setText("Resultaten")
        self.res_count.setText(f"{n} gevonden")

    def _on_result(self, url, title, snippet):
        # Verwijder laad label
        for i in range(self.res_ly.count()):
            item = self.res_ly.itemAt(i)
            if item and item.widget():
                w = item.widget()
                if w.objectName() == "loading_lbl":
                    w.deleteLater(); break

        card = ResultCard(url, title, snippet)
        card.clicked.connect(self._open)
        count = self.res_ly.count()
        self.res_ly.insertWidget(count-1, card)

        # Update teller
        cur = self.res_count.text().replace(" gevonden","")
        try: n = int(cur)+1
        except: n = 1
        self.res_count.setText(f"{n} gevonden")

    def _open(self, url):
        self.url_bar.setText(url)
        self.webview.setUrl(QUrl(url))

    def _clear_results(self):
        while self.res_ly.count() > 1:
            item = self.res_ly.takeAt(0)
            if item and item.widget():
                item.widget().deleteLater()

    # ── Index crawl ───────────────────────────────────────────
    def _add_seed(self):
        url = self.seed_input.text().strip()
        if not url: return
        if not url.startswith("http"): url = "https://"+url
        self.seed_input.clear()
        # Start direct een mini-crawl voor deze URL
        t = BgCrawler([url], self._tor_on, delay=1.0)
        t.status.connect(lambda s,p,v: (
            self.crawl_status.setText(s),
            self.sb_pages.setText(f"📄 {p} paginas")))
        t.start()
        self.crawl_status.setText(f"🕷 Indexeren: {url[:40]}")
        self.crawl_status.setStyleSheet(
            "color:#7ec87e;font-size:11px;")

    def _show_index(self):
        """Toon alle geindexeerde paginas."""
        d = QDialog(self)
        d.setWindowTitle("📚 Geindexeerde paginas")
        d.resize(900, 600)
        d.setStyleSheet(
            "QDialog{background:#0a0a0f;color:#e8e4d8;}"
            "QLineEdit{background:#111118;color:#e8ecf2;"
            "border:1px solid rgba(200,205,214,0.15);"
            "border-radius:8px;padding:6px 12px;}"
            "QPushButton{background:#1a1a24;color:#e8ecf2;"
            "border:1px solid rgba(200,205,214,0.12);"
            "border-radius:8px;padding:6px 16px;font-weight:700;}"
            "QPushButton:hover{background:#22222e;}")
        ly = QVBoxLayout(d)
        ly.setContentsMargins(16,16,16,16); ly.setSpacing(10)

        # Header
        hdr = QHBoxLayout()
        p, v = db_stats()
        title_lbl = QLabel(f"📚 {p} paginas geindexeerd  •  {v} bezocht")
        title_lbl.setStyleSheet(
            "font-size:15px;font-weight:700;color:#e8ecf2;")
        hdr.addWidget(title_lbl)
        hdr.addStretch()

        # Zoek in index
        search_box = QLineEdit()
        search_box.setPlaceholderText("Zoek in index...")
        search_box.setFixedWidth(220)
        hdr.addWidget(search_box)

        btn_del_sel = QPushButton("🗑 Verwijder geselecteerde")
        btn_del_sel.setStyleSheet(
            "QPushButton{background:#1a0a0a;color:#e74c3c;"
            "border:1px solid rgba(231,76,60,0.2);"
            "border-radius:8px;padding:6px 14px;font-size:12px;}"
            "QPushButton:hover{background:#221212;}")
        hdr.addWidget(btn_del_sel)
        ly.addLayout(hdr)

        # Tabel
        from PyQt6.QtWidgets import QTableWidget, QTableWidgetItem, QHeaderView, QAbstractItemView
        table = QTableWidget()
        table.setColumnCount(4)
        table.setHorizontalHeaderLabels(
            ["Titel","URL","Datum","Acties"])
        table.horizontalHeader().setSectionResizeMode(
            0, QHeaderView.ResizeMode.Stretch)
        table.horizontalHeader().setSectionResizeMode(
            1, QHeaderView.ResizeMode.Stretch)
        table.setColumnWidth(2, 120)
        table.setColumnWidth(3, 80)
        table.setSelectionBehavior(
            QAbstractItemView.SelectionBehavior.SelectRows)
        table.setEditTriggers(
            QAbstractItemView.EditTrigger.NoEditTriggers)
        table.setStyleSheet("""
            QTableWidget{background:#111118;
                border:1px solid rgba(200,205,214,0.1);
                border-radius:8px;gridline-color:#1a1a24;}
            QTableWidget::item{padding:6px;color:#c8cdd6;
                border-bottom:1px solid #1a1a24;}
            QTableWidget::item:selected{
                background:rgba(126,184,247,0.15);
                color:#e8ecf2;}
            QHeaderView::section{background:#0d0d12;
                color:#7eb8f7;padding:8px;font-weight:700;
                border:none;border-bottom:1px solid #1a1a24;}
        """)
        ly.addWidget(table)

        def load_pages(filter_txt=""):
            table.setRowCount(0)
            try:
                con = sqlite3.connect(DB_FILE)
                cur = con.cursor()
                if filter_txt:
                    lk = f"%{filter_txt}%"
                    cur.execute("""SELECT id,title,url,crawled
                        FROM pages WHERE title LIKE ? OR url LIKE ?
                        ORDER BY crawled DESC LIMIT 500""",
                        (lk,lk))
                else:
                    cur.execute("""SELECT id,title,url,crawled
                        FROM pages ORDER BY crawled DESC LIMIT 500""")
                rows = cur.fetchall()
                con.close()
                table.setRowCount(len(rows))
                for i,(pid,title,url,crawled) in enumerate(rows):
                    table.setItem(i,0,QTableWidgetItem(
                        title or "(geen titel)"))
                    table.setItem(i,1,QTableWidgetItem(url))
                    date = (crawled or "")[:10]
                    table.setItem(i,2,QTableWidgetItem(date))
                    # Verwijder knop
                    del_btn = QPushButton("🗑")
                    del_btn.setStyleSheet(
                        "QPushButton{background:transparent;"
                        "color:#e74c3c;border:none;font-size:14px;}"
                        "QPushButton:hover{color:#ff6b6b;}")
                    del_btn.setProperty("page_id", pid)
                    def make_del(page_id, row_url):
                        def do_del():
                            try:
                                c = sqlite3.connect(DB_FILE)
                                c.execute(
                                    "DELETE FROM pages WHERE id=?",
                                    (page_id,))
                                c.execute(
                                    "DELETE FROM pages_fts WHERE rowid=?",
                                    (page_id,))
                                c.commit(); c.close()
                            except: pass
                            load_pages(search_box.text())
                        return do_del
                    del_btn.clicked.connect(
                        make_del(pid, url))
                    table.setCellWidget(i,3,del_btn)
                title_lbl.setText(
                    f"📚 {len(rows)} van {db_stats()[0]} paginas")
            except Exception as e:
                print(f"Index load fout: {e}")

        # Open in browser bij dubbelklik
        def on_double_click(row, col):
            url_item = table.item(row, 1)
            if url_item:
                self._open(url_item.text())
                d.close()
        table.cellDoubleClicked.connect(on_double_click)

        # Verwijder geselecteerde
        def del_selected():
            rows = set(i.row() for i in table.selectedItems())
            ids = []
            for r in rows:
                url_item = table.item(r,1)
                if url_item:
                    try:
                        con = sqlite3.connect(DB_FILE)
                        cur = con.cursor()
                        cur.execute(
                            "SELECT id FROM pages WHERE url=?",
                            (url_item.text(),))
                        row_data = cur.fetchone()
                        if row_data:
                            ids.append(row_data[0])
                        con.close()
                    except: pass
            if ids:
                con = sqlite3.connect(DB_FILE)
                for pid in ids:
                    con.execute(
                        "DELETE FROM pages WHERE id=?", (pid,))
                    con.execute(
                        "DELETE FROM pages_fts WHERE rowid=?",
                        (pid,))
                con.commit(); con.close()
                load_pages(search_box.text())

        btn_del_sel.clicked.connect(del_selected)
        search_box.textChanged.connect(load_pages)

        # Footer
        foot = QHBoxLayout()
        btn_close = QPushButton("Sluiten")
        btn_close.clicked.connect(d.close)
        foot.addStretch()
        foot.addWidget(btn_close)
        ly.addLayout(foot)

        load_pages()
        d.exec()

    def _toggle_crawl(self):
        if self._bg_crawler and self._bg_crawler.isRunning():
            self._bg_crawler.stop()
            self._bg_crawler.wait(2000)
            self._bg_crawler = None
            self.crawl_btn.setText("🕷 Start Index Crawl")
            self.crawl_btn.setStyleSheet(
                "QPushButton{background:#0d2010;color:#7ec87e;"
                "border:1px solid rgba(126,200,126,0.2);"
                "border-radius:8px;padding:6px;font-weight:700;"
                "font-size:12px;}"
                "QPushButton:hover{background:#122816;}")
            self.crawl_status.setText("⏸ Gestopt")
            self.crawl_status.setStyleSheet(
                "color:#a0a0b8;font-size:12px;font-weight:600;")
        else:
            # Controleer of er een URL is ingevoerd
            seed = self.seed_input.text().strip()
            if not seed:
                self.crawl_status.setText(
                    "⚠ Voer eerst een URL in en klik + Add")
                self.crawl_status.setStyleSheet(
                    "color:#e67e22;font-size:12px;font-weight:600;")
                # Reset knop zodat hij niet blijft hangen
                self.crawl_btn.setChecked(False) if hasattr(
                    self.crawl_btn, "isChecked") else None
                return
            # Voeg seed toe en start
            url = seed if seed.startswith("http") else "https://"+seed
            self.seed_input.clear()
            self.crawl_btn.setText("⏹ Stop Crawl")
            self.crawl_btn.setStyleSheet(
                "QPushButton{background:#2a1a1a;color:#e74c3c;"
                "border:1px solid rgba(231,76,60,0.2);"
                "border-radius:8px;padding:6px;font-weight:700;"
                "font-size:12px;}"
                "QPushButton:hover{background:#331a1a;}")
            self.crawl_status.setText(f"🕷 Indexeren: {url[:35]}...")
            self.crawl_status.setStyleSheet(
                "color:#7ec87e;font-size:12px;font-weight:600;")
            self._bg_crawler = BgCrawler([url], self._tor_on)
            self._bg_crawler.status.connect(
                lambda s,p,v: (
                    self.crawl_status.setText(s),
                    self.sb_pages.setText(f"📄 {p} paginas")))
            self._bg_crawler.done.connect(self._on_crawl_done)
            self._bg_crawler.start()

    def _on_crawl_done(self):
        self.crawl_btn.setText("🕷 Start Index Crawl")
        self.crawl_btn.setStyleSheet(
            "QPushButton{background:#0d2010;color:#7ec87e;"
            "border:1px solid rgba(126,200,126,0.2);"
            "border-radius:8px;padding:6px;font-weight:700;"
            "font-size:12px;}"
            "QPushButton:hover{background:#122816;}")
        p, v = db_stats()
        self.crawl_status.setText(
            f"✅ Klaar — {p} paginas in index")
        self.crawl_status.setStyleSheet(
            "color:#7ec87e;font-size:12px;font-weight:600;")
        self.sb_pages.setText(f"📄 {p} paginas")

    def _clear_index(self):
        r = QMessageBox.question(self, "Index wissen",
            "Weet je zeker dat je de index wil wissen?",
            QMessageBox.StandardButton.Yes |
            QMessageBox.StandardButton.No)
        if r == QMessageBox.StandardButton.Yes:
            con = sqlite3.connect(DB_FILE)
            con.executescript(
                "DELETE FROM pages;"
                "DELETE FROM pages_fts;"
                "DELETE FROM visited;")
            con.commit(); con.close()
            self.crawl_status.setText("🗑 Index gewist")
            self._show_home()

    # ── Tor ───────────────────────────────────────────────────
    def _start_tor_default(self):
        """Start Tor automatisch bij opstarten."""
        self.tor_btn.setChecked(True)
        self._toggle_tor()

    def _toggle_tor(self):
        if not self.tor_btn.isChecked():
            self._tor_on = False
            self.sb_tor.setText("🧅 Tor: UIT")
            self.sb_tor.setStyleSheet("color:#c0392b;")
            self.tor_btn.setText("🧅 Tor: UIT")
            # Stop en reset tor manager volledig
            if self._tor_mgr:
                self._tor_mgr.stop()
                self._tor_mgr.wait(3000)
                self._tor_mgr = None
            # Reset search thread
            if self._search_thr and self._search_thr.isRunning():
                self._search_thr.stop()
                self._search_thr = None
            self.crawl_status.setText("🧅 Tor uitgeschakeld")
            self.crawl_status.setStyleSheet(
                "color:#a0a0b8;font-size:12px;font-weight:600;")
            self.crawl_status.setText("⏸ Klaar")
            self.crawl_status.setStyleSheet("color:#3a3a5a;font-size:11px;")
            return

        # Zorg dat vorige manager klaar is
        if self._tor_mgr:
            self._tor_mgr.stop()
            self._tor_mgr.wait(2000)
            self._tor_mgr = None

        self.tor_btn.setText("🧅 Tor: verbinden...")
        self.sb_tor.setText("🧅 Tor: verbinden...")
        self.sb_tor.setStyleSheet("color:#e67e22;")
        self._tor_mgr = TorManager()
        self._tor_mgr.status.connect(
            lambda s: self.sb_tor.setText(s))
        self._tor_mgr.ready.connect(self._on_tor)
        self._tor_mgr.start()

    def _on_tor(self, ok):
        self._tor_on = ok
        # Reset search thread zodat nieuwe zoekopdrachten de juiste instelling gebruiken
        if self._search_thr and self._search_thr.isRunning():
            self._search_thr.stop()
            self._search_thr = None
        if ok:
            self.sb_tor.setText("🧅 Tor: ✅ AAN")
            self.sb_tor.setStyleSheet("color:#27ae60;")
            self.tor_btn.setText("🧅 Tor: AAN")
            self.crawl_status.setText("🧅 Tor actief — zoeken werkt via Tor")
            self.crawl_status.setStyleSheet("color:#27ae60;font-size:11px;")
        else:
            self._tor_on = False
            self.tor_btn.setChecked(False)
            self.tor_btn.setText("🧅 Tor: UIT")
            self.sb_tor.setText("🧅 Tor: FOUT")
            self.sb_tor.setStyleSheet("color:#e74c3c;")
            self.crawl_status.setText("❌ Tor kon niet verbinden")
            self.crawl_status.setStyleSheet("color:#e74c3c;font-size:11px;")

    # ── Stats ─────────────────────────────────────────────────
    def _refresh_stats(self):
        p, v = db_stats()
        self.sb_pages.setText(f"📄 {p} paginas")
        QTimer.singleShot(10000, self._refresh_stats)

    def closeEvent(self, e):
        # Stop alle threads
        if self._search_thr and self._search_thr.isRunning():
            self._search_thr.stop()
            self._search_thr.wait(2000)
        if self._bg_crawler and self._bg_crawler.isRunning():
            self._bg_crawler.stop()
            self._bg_crawler.wait(2000)
        # Stop Tor volledig
        if self._tor_mgr:
            self._tor_mgr.stop()
            self._tor_mgr.wait(3000)
        # Extra zekerheid: kill tor.exe
        try:
            import subprocess
            subprocess.run(
                ["taskkill", "/F", "/IM", "tor.exe"],
                creationflags=subprocess.CREATE_NO_WINDOW,
                timeout=3)
        except: pass
        e.accept()

